      "claim": "Abecarnil has an absolute oral bioavailability of 39 ± 17% in healthy volunteers, with the mean clearly above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Mizolastine has an absolute oral bioavailability of 70% in healthy young volunteers, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Gefitinib has an oral bioavailability of about 60% in humans, providing additional high-transfer evidence for F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report oral bioavailability values well above 20%, including multiple direct human absolute bioavailability measurements ranging from about 39% to 70%. Therefore the query molecule is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself; the prediction relies on high-transfer analogues.",
    "Some analogue records are predicted or unspecified bioavailability types rather than direct absolute human measurements, though the direct absolute measurements are consistent."
  ],
